begin;
select '1..3' as tap;
create function pg_temp.require(ok boolean)returns void language plpgsql as $$begin perform set_config('p16.assert',(coalesce(nullif(current_setting('p16.assert',true),''),'0')::int+1)::text,true);if ok is distinct from true then raise exception 'P16 assertion failed %',current_setting('p16.assert');end if;end$$;
create function pg_temp.rejects(command text,code text)returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'Expected P16 rejection %',code;end$$;
create function pg_temp.pv(id uuid)returns integer language sql as $$select(public.read_task(id)->>'version')::integer$$;
create function pg_temp.task(title text)returns uuid language sql as $$select(public.create_task('22222222-2222-4222-8222-222222222221',jsonb_build_object('title',title,'summary','Synthetic dependency test','body','Private notes','classification','restricted','taskType','ordinary','leadUnitId','44444444-4444-4444-8444-444444444441','assigneeId','33333333-3333-4333-8333-333333333332','assignedUnitId','44444444-4444-4444-8444-444444444441','collaborators','[]'::jsonb,'checklist','[]'::jsonb,'dueOn','2027-04-10','dueAt',null,'parentId',null,'reason','Synthetic dependency test'),gen_random_uuid())->>'workItemId')::uuid$$;
grant execute on function pg_temp.require(boolean),pg_temp.rejects(text,text),pg_temp.pv(uuid),pg_temp.task(text)to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select set_config('p16.a',pg_temp.task('PRIVATE P16 predecessor')::text,true);
select set_config('p16.b',pg_temp.task('Fictional P16 successor')::text,true);
