select set_config('p16.av',pg_temp.pv(current_setting('p16.a')::uuid)::text,true);
select set_config('p16.bv',pg_temp.pv(current_setting('p16.b')::uuid)::text,true);
select pg_temp.rejects($q$select public.add_task_dependency(current_setting('p16.a')::uuid,current_setting('p16.a')::uuid,'finish_to_start',true,1,1,'No self edge',gen_random_uuid())$q$,'22023');
select set_config('p16.edge',public.add_task_dependency(current_setting('p16.a')::uuid,current_setting('p16.b')::uuid,'finish_to_start',true,1,1,'Required predecessor','16000000-0000-4000-8000-000000000001')->>'dependencyId',true);
select pg_temp.require(public.add_task_dependency(current_setting('p16.a')::uuid,current_setting('p16.b')::uuid,'finish_to_start',true,1,1,'Required predecessor','16000000-0000-4000-8000-000000000001')->>'dependencyId'=current_setting('p16.edge'));
select pg_temp.rejects($q$select public.add_task_dependency(current_setting('p16.b')::uuid,current_setting('p16.a')::uuid,'informational',false,pg_temp.pv(current_setting('p16.b')::uuid),1,'Inverse edge',gen_random_uuid())$q$,'55000');
select pg_temp.require(exists(select 1 from pg_locks where locktype='advisory'and pid=pg_backend_pid()and granted));
select 'ok 1 - P16_A1: self/cyclic/inverse edges rejected; exact retry retains one edge; transaction graph advisory lock held (actual parallel sessions unverified)'as tap;
select pg_temp.require((public.read_task_dependencies(current_setting('p16.b')::uuid)->>'blocked')::boolean);
select pg_temp.rejects($q$select public.transition_task(current_setting('p16.b')::uuid,'{"state":"in_progress","reason":"Cannot start"}',pg_temp.pv(current_setting('p16.b')::uuid),gen_random_uuid())$q$,'55000');
select pg_temp.rejects($q$select public.transition_task(current_setting('p16.b')::uuid,'{"state":"done","reason":"Cannot finish","evidence":"Not enough"}',pg_temp.pv(current_setting('p16.b')::uuid),gen_random_uuid())$q$,'55000');
select public.add_task_dependency(current_setting('p16.a')::uuid,current_setting('p16.c')::uuid,'informational',false,1,1,'Information only',gen_random_uuid());
select public.transition_task(current_setting('p16.c')::uuid,'{"state":"in_progress","reason":"Informational link permits start"}',pg_temp.pv(current_setting('p16.c')::uuid),gen_random_uuid());
select pg_temp.require(not(public.read_task_dependencies(current_setting('p16.c')::uuid)->>'blocked')::boolean);
select public.transition_task(current_setting('p16.a')::uuid,'{"state":"cancelled","reason":"Cancelled predecessor is unresolved"}',1,gen_random_uuid());
select pg_temp.require((public.read_task_dependencies(current_setting('p16.b')::uuid)->>'blocked')::boolean);
select pg_temp.rejects($q$select public.remove_task_dependency(current_setting('p16.edge')::uuid,pg_temp.pv(current_setting('p16.a')::uuid),pg_temp.pv(current_setting('p16.b')::uuid),'Implicit waiver forbidden',false,gen_random_uuid())$q$,'42501');
select set_config('p16.xpv',pg_temp.pv(current_setting('p16.a')::uuid)::text,true);select set_config('p16.xsv',pg_temp.pv(current_setting('p16.b')::uuid)::text,true);
select public.remove_task_dependency(current_setting('p16.edge')::uuid,current_setting('p16.xpv')::int,current_setting('p16.xsv')::int,'Explicit approved scope change; no FIN/MCD waiver',true,'16000000-0000-4000-8000-000000000002');
select public.remove_task_dependency(current_setting('p16.edge')::uuid,current_setting('p16.xpv')::int,current_setting('p16.xsv')::int,'Explicit approved scope change; no FIN/MCD waiver',true,'16000000-0000-4000-8000-000000000002');
select pg_temp.require(not(public.read_task_dependencies(current_setting('p16.b')::uuid)->>'blocked')::boolean);
select pg_temp.require(exists(select 1 from jsonb_array_elements(public.read_task_dependencies(current_setting('p16.b')::uuid)->'history')e where e->>'operation'='scope_exception'));
select set_config('p16.d',pg_temp.task('Fictional completed predecessor')::text,true);
select set_config('p16.e',pg_temp.task('Fictional unblocked successor')::text,true);
select public.add_task_dependency(current_setting('p16.d')::uuid,current_setting('p16.e')::uuid,'finish_to_start',true,1,1,'Completion unlock test',gen_random_uuid());
select public.transition_task(current_setting('p16.d')::uuid,'{"state":"done","reason":"Finished predecessor","evidence":"Synthetic final evidence"}',1,gen_random_uuid());
select pg_temp.require(not(public.read_task_dependencies(current_setting('p16.e')::uuid)->>'blocked')::boolean);
select public.transition_task(current_setting('p16.e')::uuid,'{"state":"in_progress","reason":"Predecessor completed"}',pg_temp.pv(current_setting('p16.e')::uuid),gen_random_uuid());
reset role;
select pg_temp.rejects($q$update public.tasks set workflow_state='todo'where work_item_id=current_setting('p16.d')::uuid$q$,'55000');
select pg_temp.rejects($q$update public.task_dependency_events set reason='Rewrite immutable history'$q$,'42501');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select 'ok 2 - P16_A2: unfinished and cancelled predecessors block start/completion; informational does not; explicit reasoned managerial exception removes only dependency gate'as tap;
reset role;
insert into public.record_grants(organization_id,term_id,work_item_id,member_id,grant_kind,expires_at,grantor_id)values('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222221',current_setting('p16.c')::uuid,'33333333-3333-4333-8333-333333333333','read',statement_timestamp()+interval'1 day','66666666-6666-4666-8666-666666666662');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select pg_temp.require(public.read_task(current_setting('p16.a')::uuid)is null);
select pg_temp.require(public.read_task_dependencies(current_setting('p16.c')::uuid)->'items'='[]');
select pg_temp.require(public.read_task_dependencies(current_setting('p16.c')::uuid)->'history'='[]');
select pg_temp.require((public.read_task_dependencies(current_setting('p16.c')::uuid)->>'restricted')::boolean);
select pg_temp.require(public.read_task_dependencies(current_setting('p16.c')::uuid)::text not like '%PRIVATE P16%');
select pg_temp.require(public.read_task_dependencies(current_setting('p16.c')::uuid)::text not like '%'||current_setting('p16.a')||'%');
select pg_temp.require(public.read_task_dependencies(current_setting('p16.c')::uuid)->'options'='[]');
select pg_temp.rejects($q$select * from public.task_dependencies$q$,'42501');
select pg_temp.rejects($q$select public.add_task_dependency(current_setting('p16.a')::uuid,current_setting('p16.c')::uuid,'finish_to_start',true,1,1,'No authority',gen_random_uuid())$q$,'42501');
