insert into public.record_grants(organization_id,term_id,work_item_id,member_id,grant_kind,expires_at,grantor_id)values('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222221',current_setting('p16.d')::uuid,'33333333-3333-4333-8333-333333333333','read',statement_timestamp()+interval'1 day','66666666-6666-4666-8666-666666666662');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select pg_temp.require((public.read_task_dependencies(current_setting('p16.d')::uuid)->>'restrictedNextSteps')::boolean);
select pg_temp.require(public.read_task_dependencies(current_setting('p16.d')::uuid)->'nextSteps'='[]');
select pg_temp.require(public.read_task_dependencies(current_setting('p16.d')::uuid)::text not like '%'||current_setting('p16.e')||'%');
