update public.role_assignments set status='revoked'where term_membership_id='66666666-6666-4666-8666-666666666662'and role_id='55555555-5555-4555-8555-555555555559';
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select pg_temp.rejects($q$select public.remove_task_dependency(current_setting('p16.edge')::uuid,current_setting('p16.xpv')::int,current_setting('p16.xsv')::int,'Explicit approved scope change; no FIN/MCD waiver',true,'16000000-0000-4000-8000-000000000002')$q$,'42501');
select 'ok 3 - P16_A3: restricted predecessor exposes only neutral association/readiness; no ID/title/count/history or raw table leakage; both-record edit authorization required'as tap;
